    local function persistentToggle(card, key, apply)
        local saved = config.Get(key, false)
        card:AddToggle(saved, function(state)
            config.Set(key, state)
            apply(state)
        end)
        if saved then
            apply(true)
        end
    end
    local getCurrentPlot = import(S(482))
    local getPlotParts = import(S(435))
    local dumpInstance = import(S(237))
    local dumpRemotes = import(S(125))(import)
    local dumpSellCards = import(S(434))(import)
