    ), S(352), autoUpgrade.SetEnabled)
    local debugCard = farmTab:AddCard(S(460), S(12))
    local checkBtn
    checkBtn = debugCard:AddButton(S(261), function()
        local plot = getCurrentPlot()
        if not plot then
            checkBtn.Text = S(49)
            log(S(161))
            return
        end
        local parts = getPlotParts(plot)
        local nodeCount = parts.Nodes and #parts.Nodes:GetChildren() or 0
        local holderCount = parts.Holders and #parts.Holders:GetChildren() or 0
        checkBtn.Text = plot.Name
        log(string.format(
            S(258),
            plot.Name, nodeCount, holderCount
        ))
    end)
    local dumpCard = farmTab:AddCard(
        S(455),
        S(98)
    )
    local dumpBtn
    dumpBtn = dumpCard:AddButton(S(202), function()
        local plot = getCurrentPlot()
        if not plot then
            dumpBtn.Text = S(397)
            return
        end
        local ok, err = log(S(106))
        if not ok then
            dumpBtn.Text = S(109)
            dumpCard:SetSubtitle(S(509) .. tostring(err))
            return
        end
        local parts = getPlotParts(plot)
        local firstNode = parts.Nodes and parts.Nodes:GetChildren()[1]
        if firstNode then
            log(S(121) .. firstNode.Name .. S(120))
            dumpInstance(firstNode, log)
        else
            log(S(529))
        end
        local firstHolder = parts.Holders and parts.Holders:GetChildren()[1]
        if firstHolder then
            log(S(391) .. firstHolder.Name .. S(541))
            dumpInstance(firstHolder, log)
        else
            log(S(377))
        end
        dumpBtn.Text = S(469)
    end)
    local toolDumpCard = farmTab:AddCard(
